/bin/zsh -lc "python3 -B - <<'PY'
import sqlite3

# Distinguish REPLACE observation from original DELETE-trigger execution.
for replacement in (10, 11):
    with sqlite3.connect(':memory:') as con:
        deleting = [False]
        con.create_function('statement_kind', 1, lambda value: deleting.__setitem__(-1, bool(value)))
        con.create_function('explicit_delete', 0, lambda: int(deleting[-1]))
        con.executescript('''
          CREATE TABLE accounts(tenant, name, balance, PRIMARY KEY(tenant,name));
          CREATE TABLE audit(tenant, target);
          INSERT INTO accounts VALUES ('one','b',10);
          PRAGMA recursive_triggers=ON;
          CREATE TEMP TABLE effects(tenant,name,balance,delta);
          CREATE TEMP TRIGGER observed_delete AFTER DELETE ON accounts BEGIN
            INSERT INTO effects VALUES(OLD.tenant,OLD.name,OLD.balance,-1);
          END;
          CREATE TEMP TRIGGER observed_insert AFTER INSERT ON accounts BEGIN
            INSERT INTO effects VALUES(NEW.tenant,NEW.name,NEW.balance,1);
          END;
          CREATE TRIGGER disallow_deletion BEFORE DELETE ON accounts
          WHEN explicit_delete() BEGIN
            SELECT RAISE(ABORT,'unexpected delete trigger');
          END;
        ''')
        con.execute('CREATE TRIGGER replace_row AFTER INSERT ON audit BEGIN '
                    'SELECT statement_kind(0); '
                    'INSERT OR REPLACE INTO accounts VALUES (NEW.tenant,NEW.target,'
                    + str(replacement) + '); END')
        con.execute(\"INSERT INTO audit VALUES('one','b')\")
        delta = con.execute('SELECT balance,SUM(delta) FROM effects GROUP BY balance HAVING SUM(delta)<>0').fetchall()
        print('replacement balance:', replacement, 'unexpected delta:', delta)
        assert bool(delta) == (replacement "'!= 10)
        deleting[-1] = True
        try:
            con.execute("DELETE FROM accounts WHERE tenant='"'one' AND name='b'\")
        except sqlite3.IntegrityError as exc:
            print('explicit DELETE preserved:', str(exc))
        else:
            raise AssertionError('DELETE trigger suppressed')
PY"

